# Script to analyze the checker.py challenge file

# Open the checker.py file and inspect key functions like 'up', 'right', 'down', 'left', and 'encode'
def analyze():
    with open('/home/ctfplayer/ctf_files/checker.py', 'r') as file:
        lines = file.readlines()
        for i, line in enumerate(lines):
            if any(keyword in line for keyword in ['def up', 'def right', 'def down', 'def left', 'def encode']):
                print(f'\nFunction found on line {i+1}:\n')
            print(line, end='')

if __name__ == "__main__":
    analyze()

